class Base {
protected:
    struct InnerConfig {
        int val = 0;
    };
    InnerConfig cfg;
};

class Derived : public Base {
public:
    void setup() {
        // SUCCESS: Derived uses Base::InnerConfig directly
        InnerConfig temp;
        temp.val = 5;
        cfg = temp;
    }
};

